    contentKh: `១. គោលបំណង PURPOSE
ដើម្បីបង្កើតនីតិវិធីឆ្លើយតបបន្ទាន់ក្នុងការការពារអាយុជីវិតកម្មករ និងទ្រព្យសម្បត្តិរោងចក្រពីគ្រោះទឹកជំនន់ ឬជំនន់ទឹកភ្លៀងធ្ងន់ធ្ងរ។

២. ដែនកំណត់ SCOPE
គោលនយោបាយនេះអនុវត្តចំពោះគ្រប់ផ្នែកផលិតកម្ម រដ្ឋបាល ឃ្លាំង និងអ្នកម៉ៅការបន្តទាំងអស់ក្នុងរោងចក្រ។

៣. និយមន័យ DEFINITIONS
- អនុលោមភាព (Compliance): ការគោរព និងអនុវត្តតាមបទដ្ឋានច្បាប់ បទបញ្ជាផ្ទៃក្នុង និងស្តង់ដាអន្តរជាតិ។
- ការត្រួតពិនិត្យ (Monitoring): ដំណើរការតាមដានការអនុវត្តជាប្រចាំដើម្បីធានានិរន្តរភាព។

៤. នីតិវិធី PROCEDURE
- តាមដានការព្យាករណ៍អាកាសធាតុពីក្រសួងធនធានទឹក និងឧតុនិយមជាប្រចាំក្នុងរដូវវស្សា។
- រៀបចំបាវខ្សាច់ទប់ទ្វារចូល ត្រួតពិនិត្យម៉ាស៊ីនបូមទឹក និងសម្អាតប្រព័ន្ធលូបង្ហូរទឹកជារៀងរាល់សប្តាហ៍។
- លើកក្រណាត់ គ្រឿងបន្លាស់ និងម៉ាស៊ីនអគ្គិសនីឱ្យផុតពីដីយ៉ាងតិច ៣០ សង់ទីម៉ែត្រ។
- ពេលទឹកជន់លិចខ្លាំង ត្រូវកាត់ផ្តាច់ប្រព័ន្ធភ្លើងមេភ្លាមៗ និងជម្លៀសបុគ្គលិកទៅកាន់ទីទួលសុវត្ថិភាព។

៥. សិទ្ធិអំណាច និងការទទួលខុសត្រូវ AUTHORITY & RESPONSIBILITY
ប្រធានផ្នែកពាក់ព័ន្ធ និងមន្ត្រីទទួលបន្ទុកត្រូវធានាការអនុវត្តគោលការណ៍នេះឱ្យមានប្រសិទ្ធភាពខ្ពស់ និងរាយការណ៍ជូន General Manager។`,
    contentEn: `1. PURPOSE
To establish immediate emergency procedures protecting workforce safety, machinery, and finished goods from flooding.

2. SCOPE
Applies to all factory production areas, warehouses, administrative departments, and external contractors.

3. DEFINITIONS
- Compliance: Adherence to applicable national labor statutes, safety regulations, and buyer codes of conduct.
- Monitoring: Continuous routine verification to ensure sustained implementation.

4. PROCEDURE
- Monitor official weather alerts regularly during the rainy season.
- Prepare sandbags, inspect drainage water pumps, and clean internal gutters and storm drains weekly.
- Elevate fabrics, cartons, and sensitive electrical equipment at least 30 cm above floor grade.
- In severe flooding, disconnect the main electrical switchgear immediately and guide workers to designated assembly points.

5. AUTHORITY & RESPONSIBILITY
Designated department managers and compliance personnel are responsible for effective execution and reporting to the General Manager.`,
