    titleKh: 'គោលនយោបាយសេរីភាពនៃការបង្កើតសមាគម និងការចរចាជាសមូហភាព',
    titleEn: 'Freedom of Association and Collective Bargaining Policy',
    companyName: 'G.S.textileGarment(Cambodia) co.,Ltd',
    productType: 'Garment & Textile Products',
    preparedBy: 'Mr. CHAN PHEARUM',
