    approvedDate: '11-11-2024',
    contentKh: `១. គោលបំណង PURPOSE
ដើម្បីបង្កើតប្រព័ន្ធទទួល និងដោះស្រាយបណ្តឹងតវ៉ារបស់កម្មករនិយោជិតប្រកបដោយតម្លាភាព សម្ងាត់ យុត្តិធម៌ និងគ្មានការសងសឹក។

២. ដែនកំណត់ SCOPE
គោលនយោបាយនេះអនុវត្តចំពោះគ្រប់ផ្នែកផលិតកម្ម រដ្ឋបាល ឃ្លាំង និងអ្នកម៉ៅការបន្តទាំងអស់ក្នុងរោងចក្រ។

៣. និយមន័យ DEFINITIONS
- អនុលោមភាព (Compliance): ការគោរព និងអនុវត្តតាមបទដ្ឋានច្បាប់ បទបញ្ជាផ្ទៃក្នុង និងស្តង់ដាអន្តរជាតិ។
- ការត្រួតពិនិត្យ (Monitoring): ដំណើរការតាមដានការអនុវត្តជាប្រចាំដើម្បីធានានិរន្តរភាព។

៤. នីតិវិធី PROCEDURE
- ឆានែលដាក់ពាក្យបណ្តឹង៖ ប្រអប់សំបុត្រសម្ងាត់ (បើក ១ ដង/សប្តាហ៍), លេខទូរស័ព្ទទាន់ហេតុការណ៍ (Hotline), ឬជួបផ្ទាល់ជាមួយ HR។
- គណៈកម្មាធិការដោះស្រាយបណ្តឹង (តំណាងរដ្ឋបាល + តំណាងកម្មករ) បើកស្រោមសំបុត្ររួមគ្នា។
- ស៊ើបអង្កេត និងឆ្លើយតបដំណោះស្រាយជាលាយលក្ខណ៍អក្សរក្នុងរយៈពេល ៧ ថ្ងៃនៃថ្ងៃធ្វើការ។
- រក្សាការសម្ងាត់ ១០០% លើអត្តសញ្ញាណអ្នកប្តឹង និងការពារមិនឱ្យមានការសងសឹកដាច់ខាត។

៥. សិទ្ធិអំណាច និងការទទួលខុសត្រូវ AUTHORITY & RESPONSIBILITY
ប្រធានផ្នែកពាក់ព័ន្ធ និងមន្ត្រីទទួលបន្ទុកត្រូវធានាការអនុវត្តគោលការណ៍នេះឱ្យមានប្រសិទ្ធភាពខ្ពស់ និងរាយការណ៍ជូន General Manager។`,
    contentEn: `1. PURPOSE
To establish a fair, transparent, accessible, and confidential grievance mechanism resolving worker complaints without fear of retaliation.

2. SCOPE
Applies to all factory production areas, warehouses, administrative departments, and external contractors.

3. DEFINITIONS
- Compliance: Adherence to applicable national labor statutes, safety regulations, and buyer codes of conduct.
- Monitoring: Continuous routine verification to ensure sustained implementation.

4. PROCEDURE
- Intake channels include locked confidential suggestion boxes (opened weekly), a direct telephone hotline, or in-person reporting.
- The Grievance Committee (joint management and worker representatives) jointly witnesses box openings.
- Investigate complaints impartially and provide written responses within 7 working days.
- Guarantee complete confidentiality of complainant identity and strictly forbid any form of retaliation.

5. AUTHORITY & RESPONSIBILITY
Designated department managers and compliance personnel are responsible for effective execution and reporting to the General Manager.`,
