    contentKh: `១. គោលបំណង PURPOSE
ដើម្បីលុបបំបាត់ការរើសអើងចំពោះបុគ្គលិកដែលផ្ទុកមេរោគអេដស៍ ការពារសិទ្ធិការងារ និងរក្សាការសម្ងាត់ព័ត៌មានវេជ្ជសាស្ត្រ។

២. ដែនកំណត់ SCOPE
គោលនយោបាយនេះអនុវត្តចំពោះគ្រប់ផ្នែកផលិតកម្ម រដ្ឋបាល ឃ្លាំង និងអ្នកម៉ៅការបន្តទាំងអស់ក្នុងរោងចក្រ។

៣. និយមន័យ DEFINITIONS
- អនុលោមភាព (Compliance): ការគោរព និងអនុវត្តតាមបទដ្ឋានច្បាប់ បទបញ្ជាផ្ទៃក្នុង និងស្តង់ដាអន្តរជាតិ។
- ការត្រួតពិនិត្យ (Monitoring): ដំណើរការតាមដានការអនុវត្តជាប្រចាំដើម្បីធានានិរន្តរភាព។

៤. នីតិវិធី PROCEDURE
- ក្រុមហ៊ុនមិនតម្រូវឱ្យធ្វើតេស្តឈាមរកមេរោគអេដស៍ជាលក្ខខណ្ឌមុនចូលបម្រើការងារ ឬបន្តការងារឡើយ។
- ស្ថានភាពផ្ទុកមេរោគអេដស៍មិនមែនជាមូលហេតុនៃការបដិសេធការងារ ឬការបញ្ឈប់ពីការងារឡើយ។
- ព័ត៌មានវេជ្ជសាស្ត្ររបស់បុគ្គលិកត្រូវរក្សាទុកជាការសម្ងាត់ដាច់ខាត។
- ផ្សព្វផ្សាយចំណេះដឹងស្តីពីវិធីបង្ការ និងការមិនចម្លងមេរោគអេដស៍នៅកន្លែងធ្វើការ។

៥. សិទ្ធិអំណាច និងការទទួលខុសត្រូវ AUTHORITY & RESPONSIBILITY
ប្រធានផ្នែកពាក់ព័ន្ធ និងមន្ត្រីទទួលបន្ទុកត្រូវធានាការអនុវត្តគោលការណ៍នេះឱ្យមានប្រសិទ្ធភាពខ្ពស់ និងរាយការណ៍ជូន General Manager។`,
    contentEn: `1. PURPOSE
To eliminate stigma and discrimination against employees living with HIV/AIDS, ensuring equal employment rights and medical privacy.

2. SCOPE
Applies to all factory production areas, warehouses, administrative departments, and external contractors.

3. DEFINITIONS
- Compliance: Adherence to applicable national labor statutes, safety regulations, and buyer codes of conduct.
- Monitoring: Continuous routine verification to ensure sustained implementation.

4. PROCEDURE
- Mandatory HIV screening is strictly prohibited as a condition for hiring, contract renewal, or employment.
- HIV status shall never be a valid justification for job termination, demotion, or denied promotion.
- Maintain strict confidentiality over all employee medical data and clinic records.
- Conduct recurring awareness sessions explaining transmission facts to eliminate workplace prejudice.

5. AUTHORITY & RESPONSIBILITY
Designated department managers and compliance personnel are responsible for effective execution and reporting to the General Manager.`,
