    contentKh: `១. គោលបំណង PURPOSE
ដើម្បីបង្កើតយន្តការត្រួតពិនិត្យផ្ទៃក្នុងទៀងទាត់ វាយតម្លៃកម្រិតអនុលោមភាពតាមច្បាប់ការងារ សង្គម និងបរិស្ថាន និងចាត់វិធានការកែតម្រូវទាន់ពេល។

២. ដែនកំណត់ SCOPE
គោលនយោបាយនេះអនុវត្តចំពោះគ្រប់ផ្នែកផលិតកម្ម រដ្ឋបាល ឃ្លាំង និងអ្នកម៉ៅការបន្តទាំងអស់ក្នុងរោងចក្រ។

៣. និយមន័យ DEFINITIONS
- អនុលោមភាព (Compliance): ការគោរព និងអនុវត្តតាមបទដ្ឋានច្បាប់ បទបញ្ជាផ្ទៃក្នុង និងស្តង់ដាអន្តរជាតិ។
- ការត្រួតពិនិត្យ (Monitoring): ដំណើរការតាមដានការអនុវត្តជាប្រចាំដើម្បីធានានិរន្តរភាព។

៤. នីតិវិធី PROCEDURE
- រៀបចំកាលវិភាគសវនកម្មផ្ទៃក្នុងយ៉ាងតិច ១ ដងក្នុងមួយខែ ដោយក្រុមការងារ Compliance។
- ត្រួតពិនិត្យលើចំណុចសំខាន់ៗ៖ ពលកម្មកុមារ ម៉ោងការងារ ប្រាក់ឈ្នួល សុវត្ថិភាពអគ្គិភ័យ និងការគ្រប់គ្រងគីមី។
- ចេញរបាយការណ៍រកឃើញ (Audit Findings) និងកំណត់កាលបរិច្ឆេទបិទ CAP ក្នុងរយៈពេល ១៥-៣០ ថ្ងៃ។
- ធ្វើការផ្ទៀងផ្ទាត់ឡើងវិញ (Follow-up Audit) ដើម្បីធានាថាចំណុចខ្វះខាតត្រូវបានកែប្រែរួចរាល់។

៥. សិទ្ធិអំណាច និងការទទួលខុសត្រូវ AUTHORITY & RESPONSIBILITY
ប្រធានផ្នែកពាក់ព័ន្ធ និងមន្ត្រីទទួលបន្ទុកត្រូវធានាការអនុវត្តគោលការណ៍នេះឱ្យមានប្រសិទ្ធភាពខ្ពស់ និងរាយការណ៍ជូន General Manager។`,
    contentEn: `1. PURPOSE
To establish internal audit routines evaluating ongoing compliance with labor, social, safety, and environmental standards.

2. SCOPE
Applies to all factory production areas, warehouses, administrative departments, and external contractors.

3. DEFINITIONS
- Compliance: Adherence to applicable national labor statutes, safety regulations, and buyer codes of conduct.
- Monitoring: Continuous routine verification to ensure sustained implementation.

4. PROCEDURE
- Conduct comprehensive internal compliance audits at least once monthly led by the Compliance Team.
- Inspect critical areas: child labor prevention, working hours, payroll accuracy, fire safety, and chemicals.
- Issue formal non-conformance reports with Corrective Action Plans (CAP) due within 15-30 days.
- Perform follow-up verification audits ensuring issues are fully and permanently rectified.

5. AUTHORITY & RESPONSIBILITY
Designated department managers and compliance personnel are responsible for effective execution and reporting to the General Manager.`,
