    approvedDate: '11-11-2024',
    contentKh: `១. គោលបំណង PURPOSE
ដើម្បីគ្រប់គ្រងការផ្ទេរតួនាទី ផ្នែក ឬខ្សែសង្វាក់ការងាររបស់បុគ្គលិកឱ្យមានតម្លាភាព ផ្អែកលើសមត្ថភាព និងការយល់ព្រមពីបុគ្គលិក។

២. ដែនកំណត់ SCOPE
គោលនយោបាយនេះអនុវត្តចំពោះគ្រប់ផ្នែកផលិតកម្ម រដ្ឋបាល ឃ្លាំង និងអ្នកម៉ៅការបន្តទាំងអស់ក្នុងរោងចក្រ។

៣. និយមន័យ DEFINITIONS
- អនុលោមភាព (Compliance): ការគោរព និងអនុវត្តតាមបទដ្ឋានច្បាប់ បទបញ្ជាផ្ទៃក្នុង និងស្តង់ដាអន្តរជាតិ។
- ការត្រួតពិនិត្យ (Monitoring): ដំណើរការតាមដានការអនុវត្តជាប្រចាំដើម្បីធានានិរន្តរភាព។

៤. នីតិវិធី PROCEDURE
- ការផ្ទេរត្រូវផ្អែកលើតម្រូវការខ្សែសង្វាក់ ឬស្ថានភាពសុខភាព (ស្ត្រីមានផ្ទៃពោះត្រូវផ្ទេរមកកន្លែងស្រាល)។
- ត្រូវពិភាក្សា និងមានការព្រមព្រៀងជាលាយលក្ខណ៍អក្សរពីបុគ្គលិកយ៉ាងតិច ៧ ថ្ងៃមុនថ្ងៃចូលកាន់តួនាទីថ្មី។
- ប្រាក់បៀវត្សរ៍គោល និងអតីតភាពការងាររបស់បុគ្គលិកត្រូវរក្សាទុកនៅដដែល មិនត្រូវកាត់បន្ថយឡើយ។
- ផ្តល់ការបណ្តុះបណ្តាលតម្រង់ទិសលើជំនាញថ្មីដល់បុគ្គលិកដែលបានផ្ទេរ។

៥. សិទ្ធិអំណាច និងការទទួលខុសត្រូវ AUTHORITY & RESPONSIBILITY
ប្រធានផ្នែកពាក់ព័ន្ធ និងមន្ត្រីទទួលបន្ទុកត្រូវធានាការអនុវត្តគោលការណ៍នេះឱ្យមានប្រសិទ្ធភាពខ្ពស់ និងរាយការណ៍ជូន General Manager។`,
    contentEn: `1. PURPOSE
To manage internal job transfers and redeployments transparently based on production needs and worker consent without wage reduction.

2. SCOPE
Applies to all factory production areas, warehouses, administrative departments, and external contractors.

3. DEFINITIONS
- Compliance: Adherence to applicable national labor statutes, safety regulations, and buyer codes of conduct.
- Monitoring: Continuous routine verification to ensure sustained implementation.

4. PROCEDURE
- Transfers must align with operational requirements or medical accommodations (e.g., lighter duty for pregnancy).
- Consult with employees and provide written notification at least 7 days prior to redeployment.
- Base wages, seniority, and accrued statutory benefits remain fully protected and cannot be decreased.
- Provide hands-on training to onboard transferred employees to their new operating workstations.

5. AUTHORITY & RESPONSIBILITY
Designated department managers and compliance personnel are responsible for effective execution and reporting to the General Manager.`,
