    contentKh: `១. គោលបំណង PURPOSE
ដើម្បីរៀបចំយន្តការឆ្លើយតបរហ័សចំពោះវិបត្តិ គ្រោះអាសន្ន ឬឧប្បត្តិហេតុធ្ងន់ធ្ងរ កាត់បន្ថយការខូចខាត និងស្តារប្រតិបត្តិការឡើងវិញបានឆាប់។

២. ដែនកំណត់ SCOPE
គោលនយោបាយនេះអនុវត្តចំពោះគ្រប់ផ្នែកផលិតកម្ម រដ្ឋបាល ឃ្លាំង និងអ្នកម៉ៅការបន្តទាំងអស់ក្នុងរោងចក្រ។

៣. និយមន័យ DEFINITIONS
- អនុលោមភាព (Compliance): ការគោរព និងអនុវត្តតាមបទដ្ឋានច្បាប់ បទបញ្ជាផ្ទៃក្នុង និងស្តង់ដាអន្តរជាតិ។
- ការត្រួតពិនិត្យ (Monitoring): ដំណើរការតាមដានការអនុវត្តជាប្រចាំដើម្បីធានានិរន្តរភាព។

៤. នីតិវិធី PROCEDURE
- បង្កើតក្រុមដឹកនាំវិបត្តិ (Crisis Management Team - CMT) ដឹកនាំដោយ General Manager។
- កំណត់នីតិវិធីទាក់ទងបន្ទាន់ទៅកាន់អាជ្ញាធរដែនដី មន្ទីរពេទ្យ ប៉ូលិស និងនាយកដ្ឋានពន្លត់អគ្គិភ័យ។
- តែងតាំងអ្នកនាំពាក្យផ្លូវការតែម្នាក់គត់ ដើម្បីផ្តល់ព័ត៌មានពិតប្រាកដដល់សាធារណៈជន និងអ្នកបញ្ជាទិញ។
- ស៊ើបអង្កេតប្រភពដើម និងរៀបចំផែនការស្តារឡើងវិញភ្លាមៗបន្ទាប់ពីវិបត្តិត្រូវបានគ្រប់គ្រង។

៥. សិទ្ធិអំណាច និងការទទួលខុសត្រូវ AUTHORITY & RESPONSIBILITY
ប្រធានផ្នែកពាក់ព័ន្ធ និងមន្ត្រីទទួលបន្ទុកត្រូវធានាការអនុវត្តគោលការណ៍នេះឱ្យមានប្រសិទ្ធភាពខ្ពស់ និងរាយការណ៍ជូន General Manager។`,
    contentEn: `1. PURPOSE
To institute rapid crisis response protocols mitigating physical harm, protecting facility assets, and ensuring continuity during emergencies.

2. SCOPE
Applies to all factory production areas, warehouses, administrative departments, and external contractors.

3. DEFINITIONS
- Compliance: Adherence to applicable national labor statutes, safety regulations, and buyer codes of conduct.
- Monitoring: Continuous routine verification to ensure sustained implementation.

4. PROCEDURE
- Activate the Crisis Management Team (CMT) chaired by the General Manager during critical incidents.
- Maintain emergency speed-dial links with local authorities, referral hospitals, police, and fire departments.
- Appoint a designated official spokesperson to handle verified communications with buyers and regulators.
- Conduct root-cause evaluations and execute business continuity measures to resume safe production.

5. AUTHORITY & RESPONSIBILITY
Designated department managers and compliance personnel are responsible for effective execution and reporting to the General Manager.`,
