    contentKh: `១. គោលបំណង PURPOSE
ដើម្បីធានានូវសមធម៌ និងឱកាសស្មើគ្នាក្នុងការងារ លុបបំបាត់ការរើសអើងផ្អែកលើភេទ ជាតិសាសន៍ សាសនា ពិការភាព ឬនិន្នាការនយោបាយ។

២. ដែនកំណត់ SCOPE
គោលនយោបាយនេះអនុវត្តចំពោះគ្រប់ផ្នែកផលិតកម្ម រដ្ឋបាល ឃ្លាំង និងអ្នកម៉ៅការបន្តទាំងអស់ក្នុងរោងចក្រ។

៣. និយមន័យ DEFINITIONS
- អនុលោមភាព (Compliance): ការគោរព និងអនុវត្តតាមបទដ្ឋានច្បាប់ បទបញ្ជាផ្ទៃក្នុង និងស្តង់ដាអន្តរជាតិ។
- ការត្រួតពិនិត្យ (Monitoring): ដំណើរការតាមដានការអនុវត្តជាប្រចាំដើម្បីធានានិរន្តរភាព។

៤. នីតិវិធី PROCEDURE
- ការជ្រើសរើស ការបណ្តុះបណ្តាល ការដំឡើងប្រាក់ខែ និងការឡើងតំណែង ត្រូវផ្អែកលើសមត្ថភាព និងសមិទ្ធកម្មការងារតែមួយគត់។
- ផ្តល់ប្រាក់ឈ្នួលស្មើគ្នាសម្រាប់តម្លៃការងារស្មើគ្នា (Equal Pay for Equal Work) ដោយមិនប្រកាន់ភេទឡើយ។
- បង្កើតបរិយាកាសការងារដែលស្វាគមន៍ជនមានពិការភាព និងការគោរពសិទ្ធិស្មើគ្នា។
- បុគ្គលិកដែលរងការរើសអើងអាចដាក់ពាក្យបណ្តឹងតាមប្រព័ន្ធ Grievance Mechanism។

៥. សិទ្ធិអំណាច និងការទទួលខុសត្រូវ AUTHORITY & RESPONSIBILITY
ប្រធានផ្នែកពាក់ព័ន្ធ និងមន្ត្រីទទួលបន្ទុកត្រូវធានាការអនុវត្តគោលការណ៍នេះឱ្យមានប្រសិទ្ធភាពខ្ពស់ និងរាយការណ៍ជូន General Manager។`,
    contentEn: `1. PURPOSE
To uphold equal opportunity across all employment stages, prohibiting discrimination based on gender, race, religion, disability, or affiliation.

2. SCOPE
Applies to all factory production areas, warehouses, administrative departments, and external contractors.

3. DEFINITIONS
- Compliance: Adherence to applicable national labor statutes, safety regulations, and buyer codes of conduct.
- Monitoring: Continuous routine verification to ensure sustained implementation.

4. PROCEDURE
- Hiring, skill training, wage reviews, and career advancement must be based solely on merit, competence, and performance.
- Enforce equal compensation for work of equal value regardless of gender.
- Create an accessible, supportive workplace welcoming qualified persons with disabilities.
- Employees subjected to discriminatory acts may lodge complaints via the confidential grievance mechanism.

5. AUTHORITY & RESPONSIBILITY
Designated department managers and compliance personnel are responsible for effective execution and reporting to the General Manager.`,
