    approvedRole: 'នាយកក្រុមហ៊ុន General Manager',
    approvedDate: '11-11-2024',
    contentKh: `១. គោលបំណង PURPOSE
ដើម្បីប្រឆាំងដាច់ខាតនូវការជួញដូរមនុស្ស និងទាសភាពសម័យទំនើបក្នុងខ្សែសង្វាក់ផ្គត់ផ្គង់ និងដំណើរការជ្រើសរើសបុគ្គលិក។

២. ដែនកំណត់ SCOPE
គោលនយោបាយនេះអនុវត្តចំពោះគ្រប់ផ្នែកផលិតកម្ម រដ្ឋបាល ឃ្លាំង និងអ្នកម៉ៅការបន្តទាំងអស់ក្នុងរោងចក្រ។

៣. និយមន័យ DEFINITIONS
- អនុលោមភាព (Compliance): ការគោរព និងអនុវត្តតាមបទដ្ឋានច្បាប់ បទបញ្ជាផ្ទៃក្នុង និងស្តង់ដាអន្តរជាតិ។
- ការត្រួតពិនិត្យ (Monitoring): ដំណើរការតាមដានការអនុវត្តជាប្រចាំដើម្បីធានានិរន្តរភាព។

៤. នីតិវិធី PROCEDURE
- ហាមឃាត់ការបោកបញ្ឆោត ឬការកេងប្រវ័ញ្ចលើពលករចំណាកស្រុក និងបុគ្គលិកងាយរងគ្រោះ។
- គោលការណ៍ Employer Pays Principle: បេក្ខជនមិនត្រូវចំណាយកម្រៃជ្រើសរើស (Recruitment Fees) ណាមួយឡើយ។
- ត្រួតពិនិត្យភ្នាក់ងារជ្រើសរើសបុគ្គលិក និងអ្នកម៉ៅការបន្តឱ្យគោរពតាមបទដ្ឋានប្រឆាំងការជួញដូរមនុស្ស។
- ផ្តល់កិច្ចសន្យាការងារជាភាសាដែលកម្មករអាចអានយល់បានច្បាស់លាស់មុនពេលចាប់ផ្តើមការងារ។

៥. សិទ្ធិអំណាច និងការទទួលខុសត្រូវ AUTHORITY & RESPONSIBILITY
ប្រធានផ្នែកពាក់ព័ន្ធ និងមន្ត្រីទទួលបន្ទុកត្រូវធានាការអនុវត្តគោលការណ៍នេះឱ្យមានប្រសិទ្ធភាពខ្ពស់ និងរាយការណ៍ជូន General Manager។`,
    contentEn: `1. PURPOSE
To uphold absolute zero-tolerance against human trafficking, modern slavery, and deceptive recruitment practices in global supply chains.

2. SCOPE
Applies to all factory production areas, warehouses, administrative departments, and external contractors.

3. DEFINITIONS
- Compliance: Adherence to applicable national labor statutes, safety regulations, and buyer codes of conduct.
- Monitoring: Continuous routine verification to ensure sustained implementation.

4. PROCEDURE
- Prohibit deceptive recruitment, fraudulent job terms, or debt exploitation of migrant and vulnerable workers.
- Enforce the Employer Pays Principle: job applicants shall never pay recruitment fees, deposits, or placement charges.
- Audit recruitment agencies and labor subcontractors to ensure compliance with anti-trafficking standards.
- Provide employment contracts written in a language fully understood by the worker prior to job placement.

5. AUTHORITY & RESPONSIBILITY
Designated department managers and compliance personnel are responsible for effective execution and reporting to the General Manager.`,
