    approvedDate: '11-11-2024',
    contentKh: `១. គោលបំណង PURPOSE
ដើម្បីបង្កើតបរិយាកាសការងារប្រកបដោយសុវត្ថិភាព និងសេចក្តីថ្លៃថ្នូរ លុបបំបាត់ការបៀតបៀនផ្លូវភេទ អាកប្បកិរិយាមិនសមរម្យ និងការរំលោភបំពាន។

២. ដែនកំណត់ SCOPE
គោលនយោបាយនេះអនុវត្តចំពោះគ្រប់ផ្នែកផលិតកម្ម រដ្ឋបាល ឃ្លាំង និងអ្នកម៉ៅការបន្តទាំងអស់ក្នុងរោងចក្រ។

៣. និយមន័យ DEFINITIONS
- អនុលោមភាព (Compliance): ការគោរព និងអនុវត្តតាមបទដ្ឋានច្បាប់ បទបញ្ជាផ្ទៃក្នុង និងស្តង់ដាអន្តរជាតិ។
- ការត្រួតពិនិត្យ (Monitoring): ដំណើរការតាមដានការអនុវត្តជាប្រចាំដើម្បីធានានិរន្តរភាព។

៤. នីតិវិធី PROCEDURE
- ហាមដាច់ខាតរាល់ពាក្យសម្តី កាយវិការ ការប៉ះពាល់រាងកាយ ឬការទាមទារសេវាផ្លូវភេទជាថ្នូរនឹងការងារ/ការដំឡើងប្រាក់ខែ។
- បង្កើតគណៈកម្មាធិការប្រឆាំងការបៀតបៀនផ្លូវភេទដែលមានសមាជិកជាស្ត្រីយ៉ាងតិច ៥០%។
- ស៊ើបអង្កេតពាក្យបណ្តឹងដោយសម្ងាត់បំផុតក្នុងរយៈពេល ៥ ថ្ងៃ និងចាត់វិធានការវិន័យធ្ងន់ធ្ងរលើជនល្មើស។
- បណ្តុះបណ្តាលបុគ្គលិកគ្រប់រូបអំពីការយល់ដឹង និងការបង្ការការបៀតបៀនផ្លូវភេទ។

៥. សិទ្ធិអំណាច និងការទទួលខុសត្រូវ AUTHORITY & RESPONSIBILITY
ប្រធានផ្នែកពាក់ព័ន្ធ និងមន្ត្រីទទួលបន្ទុកត្រូវធានាការអនុវត្តគោលការណ៍នេះឱ្យមានប្រសិទ្ធភាពខ្ពស់ និងរាយការណ៍ជូន General Manager។`,
    contentEn: `1. PURPOSE
To create a safe, respectful workplace upholding individual dignity, eliminating sexual harassment, unwanted sexual conduct, and abuse.

2. SCOPE
Applies to all factory production areas, warehouses, administrative departments, and external contractors.

3. DEFINITIONS
- Compliance: Adherence to applicable national labor statutes, safety regulations, and buyer codes of conduct.
- Monitoring: Continuous routine verification to ensure sustained implementation.

4. PROCEDURE
- Strictly prohibit unwanted physical contact, sexual jokes, suggestive gestures, or demands for sexual favors for career benefits.
- Establish a Gender & Anti-Harassment Committee comprising at least 50% female representatives.
- Investigate complaints confidentially within 5 days, imposing strict disciplinary termination on perpetrators.
- Deliver annual mandatory anti-harassment training to all supervisory staff and workers.

5. AUTHORITY & RESPONSIBILITY
Designated department managers and compliance personnel are responsible for effective execution and reporting to the General Manager.`,
