    preparedDate: '01-11-2024',
    approvedBy: 'Mr. CHEN LANMAO',
    approvedRole: 'នាយកក្រុមហ៊ុន General Manager',
    approvedDate: '11-11-2024',
    contentKh: `១. គោលបំណង PURPOSE
ដើម្បីវាយតម្លៃសមិទ្ធកម្មការងារដោយតម្លាភាព លើកកម្ពស់ផលិតភាព និងពង្រឹងការប្រាស្រ័យទាក់ទងទ្វេទិសរវាងថ្នាក់គ្រប់គ្រងនិងបុគ្គលិក។

២. ដែនកំណត់ SCOPE
គោលនយោបាយនេះអនុវត្តចំពោះគ្រប់ផ្នែកផលិតកម្ម រដ្ឋបាល ឃ្លាំង និងអ្នកម៉ៅការបន្តទាំងអស់ក្នុងរោងចក្រ។

៣. និយមន័យ DEFINITIONS
- អនុលោមភាព (Compliance): ការគោរព និងអនុវត្តតាមបទដ្ឋានច្បាប់ បទបញ្ជាផ្ទៃក្នុង និងស្តង់ដាអន្តរជាតិ។
- ការត្រួតពិនិត្យ (Monitoring): ដំណើរការតាមដានការអនុវត្តជាប្រចាំដើម្បីធានានិរន្តរភាព។

៤. នីតិវិធី PROCEDURE
- រៀបចំការវាយតម្លៃសមិទ្ធកម្មការងារ (Performance Review) ២ ដងក្នុងមួយឆ្នាំ (Mid-year និង Year-end)។
- លទ្ធផលវាយតម្លៃត្រូវភ្ជាប់ទៅនឹងការដំឡើងប្រាក់ខែ ប្រាក់រង្វាន់ និងផែនការបណ្តុះបណ្តាលអភិវឌ្ឍន៍។
- ផ្តល់ឱកាសពិភាក្សា និងផ្តល់មតិកែលម្អ (Feedback & Coaching) រវាងប្រធានផ្នែក និងបុគ្គលិក។
- រៀបចំកិច្ចប្រជុំប្រចាំខែរវាងគណៈគ្រប់គ្រង និងតំណាងកម្មករដើម្បីផ្លាស់ប្តូរព័ត៌មាន។

៥. សិទ្ធិអំណាច និងការទទួលខុសត្រូវ AUTHORITY & RESPONSIBILITY
ប្រធានផ្នែកពាក់ព័ន្ធ និងមន្ត្រីទទួលបន្ទុកត្រូវធានាការអនុវត្តគោលការណ៍នេះឱ្យមានប្រសិទ្ធភាពខ្ពស់ និងរាយការណ៍ជូន General Manager។`,
    contentEn: `1. PURPOSE
To establish transparent performance appraisal standards, boosting manufacturing productivity and strengthening two-way workplace communication.

2. SCOPE
Applies to all factory production areas, warehouses, administrative departments, and external contractors.

3. DEFINITIONS
- Compliance: Adherence to applicable national labor statutes, safety regulations, and buyer codes of conduct.
- Monitoring: Continuous routine verification to ensure sustained implementation.

4. PROCEDURE
- Conduct formal performance evaluations twice annually (Mid-year and Year-end cycles).
- Link performance appraisal outcomes directly to salary reviews, annual bonuses, and promotion tracks.
- Facilitate constructive two-way feedback and coaching discussions between managers and subordinates.
- Organize monthly labor-management communication forums sharing company updates and worker suggestions.

5. AUTHORITY & RESPONSIBILITY
Designated department managers and compliance personnel are responsible for effective execution and reporting to the General Manager.`,
