    approvedDate: '11-11-2024',
    contentKh: `១. គោលបំណង PURPOSE
ដើម្បីធានាការផ្តល់ និងការប្រើប្រាស់ឧបករណ៍ការពារសុវត្ថិភាពផ្ទាល់ខ្លួន (PPE) ត្រឹមត្រូវតាមលក្ខណៈការងារ បង្ការគ្រោះថ្នាក់ការងារ។

២. ដែនកំណត់ SCOPE
គោលនយោបាយនេះអនុវត្តចំពោះគ្រប់ផ្នែកផលិតកម្ម រដ្ឋបាល ឃ្លាំង និងអ្នកម៉ៅការបន្តទាំងអស់ក្នុងរោងចក្រ។

៣. និយមន័យ DEFINITIONS
- អនុលោមភាព (Compliance): ការគោរព និងអនុវត្តតាមបទដ្ឋានច្បាប់ បទបញ្ជាផ្ទៃក្នុង និងស្តង់ដាអន្តរជាតិ។
- ការត្រួតពិនិត្យ (Monitoring): ដំណើរការតាមដានការអនុវត្តជាប្រចាំដើម្បីធានានិរន្តរភាព។

៤. នីតិវិធី PROCEDURE
- ក្រុមហ៊ុនផ្តល់ជូន PPE ស្តង់ដាដោយឥតគិតថ្លៃ៖ ស្រោមដៃដែក (ផ្នែកកាត់), ម៉ាស់ធូលី (ផ្នែកដេរ), វ៉ែនតាការពារ (ផ្នែកបោកគក់/ផ្សារ), ស្បែកជើងដែក (ផ្នែកឃ្លាំង)។
- បុគ្គលិកត្រូវពាក់ PPE ជានិច្ចពេលកំពុងបំពេញការងារនៅតំបន់ដែលបានកំណត់។
- EHS និងប្រធានផ្នែកត្រូវដើរត្រួតពិនិត្យការអនុវត្ត និងជំនួស PPE ដែលខូចខាតភ្លាមៗ។
- បុគ្គលិកដែលមិនពាក់ PPE ត្រូវទទួលការណែនាំ និងព្រមានតាមបទបញ្ជាផ្ទៃក្នុង។

៥. សិទ្ធិអំណាច និងការទទួលខុសត្រូវ AUTHORITY & RESPONSIBILITY
ប្រធានផ្នែកពាក់ព័ន្ធ និងមន្ត្រីទទួលបន្ទុកត្រូវធានាការអនុវត្តគោលការណ៍នេះឱ្យមានប្រសិទ្ធភាពខ្ពស់ និងរាយការណ៍ជូន General Manager។`,
    contentEn: `1. PURPOSE
To mandate the free provision, proper fitting, and strict utilization of certified PPE across designated factory risk zones.

2. SCOPE
Applies to all factory production areas, warehouses, administrative departments, and external contractors.

3. DEFINITIONS
- Compliance: Adherence to applicable national labor statutes, safety regulations, and buyer codes of conduct.
- Monitoring: Continuous routine verification to ensure sustained implementation.

4. PROCEDURE
- The company supplies certified PPE free of cost: steel-mesh gloves (cutting), dust masks (sewing), safety goggles (chemical/welding), steel-toed boots (warehouse).
- Workers must wear mandatory PPE at all times within designated hazard zones.
- EHS and supervisors conduct daily PPE audits, immediately replacing damaged or worn gear.
- Refusal to wear assigned safety equipment triggers progressive corrective counseling and disciplinary warnings.

5. AUTHORITY & RESPONSIBILITY
Designated department managers and compliance personnel are responsible for effective execution and reporting to the General Manager.`,
