    approvedDate: '11-11-2024',
    contentKh: `១. គោលបំណង PURPOSE
ដើម្បីបង្កើតដំណើរការជ្រើសរើសបុគ្គលិកប្រកបដោយតម្លាភាព សមធម៌ គ្មានការរើសអើង គ្មានកម្រៃជ្រើសរើស និងទប់ស្កាត់ពលកម្មកុមារ ១០០%។

២. ដែនកំណត់ SCOPE
គោលនយោបាយនេះអនុវត្តចំពោះគ្រប់ផ្នែកផលិតកម្ម រដ្ឋបាល ឃ្លាំង និងអ្នកម៉ៅការបន្តទាំងអស់ក្នុងរោងចក្រ។

៣. និយមន័យ DEFINITIONS
- អនុលោមភាព (Compliance): ការគោរព និងអនុវត្តតាមបទដ្ឋានច្បាប់ បទបញ្ជាផ្ទៃក្នុង និងស្តង់ដាអន្តរជាតិ។
- ការត្រួតពិនិត្យ (Monitoring): ដំណើរការតាមដានការអនុវត្តជាប្រចាំដើម្បីធានានិរន្តរភាព។

៤. នីតិវិធី PROCEDURE
- ផ្សព្វផ្សាយលក្ខខណ្ឌការងារ និងប្រាក់ឈ្នួលយ៉ាងច្បាស់លាស់ និងបើកចំហជាសាធារណៈ។
- ត្រួតពិនិត្យឯកសារបញ្ជាក់អាយុផ្លូវការយ៉ាងម៉ឺងម៉ាត់ មិនជ្រើសរើសបុគ្គលដែលមានអាយុក្រោម ១៨ ឆ្នាំឡើយ។
- ហាមដាច់ខាតការទារប្រាក់កម្រៃជើងសារ ឬកាត់ទុកប្រាក់កក់ពីបេក្ខជន។
- ធ្វើការសម្ភាសន៍ផ្អែកលើជំនាញ និងសមត្ថភាពជាក់ស្តែងស្របតាមសេចក្តីពិពណ៌នាមុខតំណែង (JD)។

៥. សិទ្ធិអំណាច និងការទទួលខុសត្រូវ AUTHORITY & RESPONSIBILITY
ប្រធានផ្នែកពាក់ព័ន្ធ និងមន្ត្រីទទួលបន្ទុកត្រូវធានាការអនុវត្តគោលការណ៍នេះឱ្យមានប្រសិទ្ធភាពខ្ពស់ និងរាយការណ៍ជូន General Manager។`,
    contentEn: `1. PURPOSE
To ensure equitable, merit-based, non-discriminatory recruitment, zero recruitment fees, and complete elimination of underage hiring.

2. SCOPE
Applies to all factory production areas, warehouses, administrative departments, and external contractors.

3. DEFINITIONS
- Compliance: Adherence to applicable national labor statutes, safety regulations, and buyer codes of conduct.
- Monitoring: Continuous routine verification to ensure sustained implementation.

4. PROCEDURE
- Advertise wage terms, benefits, and job requirements transparently without discriminatory restrictions.
- Strictly verify original proof-of-age documents, hiring only workers who have attained at least 18 years of age.
- Strictly prohibit demanding recruitment fees, commissions, or hiring deposits from candidates.
- Conduct structured competency-based interviews aligned with authorized Job Descriptions (JD).

5. AUTHORITY & RESPONSIBILITY
Designated department managers and compliance personnel are responsible for effective execution and reporting to the General Manager.`,
