    contentKh: `១. គោលបំណង PURPOSE
ដើម្បីកំណត់នីតិវិធីនៃការលាលែងពីការងារដោយស្ម័គ្រចិត្ត ការប្រគល់-ទទួលការងារ និងការទូទាត់ប្រាក់បំណាច់ចុងក្រោយឱ្យស្របតាមច្បាប់ការងារ។

២. ដែនកំណត់ SCOPE
គោលនយោបាយនេះអនុវត្តចំពោះគ្រប់ផ្នែកផលិតកម្ម រដ្ឋបាល ឃ្លាំង និងអ្នកម៉ៅការបន្តទាំងអស់ក្នុងរោងចក្រ។

៣. និយមន័យ DEFINITIONS
- អនុលោមភាព (Compliance): ការគោរព និងអនុវត្តតាមបទដ្ឋានច្បាប់ បទបញ្ជាផ្ទៃក្នុង និងស្តង់ដាអន្តរជាតិ។
- ការត្រួតពិនិត្យ (Monitoring): ដំណើរការតាមដានការអនុវត្តជាប្រចាំដើម្បីធានានិរន្តរភាព។

៤. នីតិវិធី PROCEDURE
- បុគ្គលិកត្រូវដាក់ពាក្យលាលែងពីការងារជាលាយលក្ខណ៍អក្សរជូន HR ដោយជូនដំណឹងមុនតាមច្បាប់ (Notice Period)។
- បំពេញទម្រង់ប្រគល់-ទទួលការងារ (Handover Clearance Form) ប្រគល់កាតបុគ្គលិក សម្ភារ និងទ្រព្យសម្បត្តិក្រុមហ៊ុន។
- ធ្វើការសម្ភាសន៍លាលែង (Exit Interview) ដើម្បីស្វែងយល់ពីមូលហេតុ និងមតិយោបល់កែលម្អ។
- គណនា និងទូទាត់ប្រាក់ឈ្នួលនៅសល់ ប្រាក់បំណាច់ឈប់សម្រាកប្រចាំឆ្នាំ និងប្រាក់អតីតភាពឱ្យបានត្រឹមត្រូវក្នុងរយៈពេល ៤៨ ម៉ោង។

៥. សិទ្ធិអំណាច និងការទទួលខុសត្រូវ AUTHORITY & RESPONSIBILITY
ប្រធានផ្នែកពាក់ព័ន្ធ និងមន្ត្រីទទួលបន្ទុកត្រូវធានាការអនុវត្តគោលការណ៍នេះឱ្យមានប្រសិទ្ធភាពខ្ពស់ និងរាយការណ៍ជូន General Manager។`,
    contentEn: `1. PURPOSE
To formalize voluntary employee resignation workflows, inventory handover, and statutory final settlement payments per labor law.

2. SCOPE
Applies to all factory production areas, warehouses, administrative departments, and external contractors.

3. DEFINITIONS
- Compliance: Adherence to applicable national labor statutes, safety regulations, and buyer codes of conduct.
- Monitoring: Continuous routine verification to ensure sustained implementation.

4. PROCEDURE
- Employees submit written resignation notice respecting statutory notice periods according to contract duration.
- Complete company property clearance, surrendering ID badges, tools, uniforms, and security assets.
- Conduct an exit interview to identify attrition root causes and opportunities for workplace enhancement.
- Finalize and disburse remaining earned wages, accrued unused annual leave pay, and seniority indemnities within 48 hours.

5. AUTHORITY & RESPONSIBILITY
Designated department managers and compliance personnel are responsible for effective execution and reporting to the General Manager.`,
