    approvedBy: 'Mr. CHEN LANMAO',
    approvedRole: 'នាយកក្រុមហ៊ុន General Manager',
    approvedDate: '11-11-2024',
    contentKh: `១. គោលបំណង PURPOSE
ដើម្បីគ្រប់គ្រងរាល់សកម្មភាពការងារដែលបង្កឱ្យមានកម្តៅ ផ្កាភ្លើង ឬអណ្តាតភ្លើង បង្ការគ្រោះអគ្គិភ័យ និងការផ្ទុះ។

២. ដែនកំណត់ SCOPE
គោលនយោបាយនេះអនុវត្តចំពោះគ្រប់ផ្នែកផលិតកម្ម រដ្ឋបាល ឃ្លាំង និងអ្នកម៉ៅការបន្តទាំងអស់ក្នុងរោងចក្រ។

៣. និយមន័យ DEFINITIONS
- អនុលោមភាព (Compliance): ការគោរព និងអនុវត្តតាមបទដ្ឋានច្បាប់ បទបញ្ជាផ្ទៃក្នុង និងស្តង់ដាអន្តរជាតិ។
- ការត្រួតពិនិត្យ (Monitoring): ដំណើរការតាមដានការអនុវត្តជាប្រចាំដើម្បីធានានិរន្តរភាព។

៤. នីតិវិធី PROCEDURE
- ត្រូវស្នើសុំលិខិតអនុញ្ញាតការងារកម្តៅ (Hot Work Permit) ពី EHS មុនចាប់ផ្តើមការងារយ៉ាងតិច ២៤ ម៉ោង។
- សម្អាតវត្ថុងាយឆេះទាំងអស់ក្នុងរង្វង់ ១១ ម៉ែត្រជុំវិញកន្លែងធ្វើការងារកម្តៅ។
- បំពាក់ឧបករណ៍ពន្លត់អគ្គិភ័យ និងចាត់តាំងអ្នកយាមភ្លើង (Fire Watcher) ម្នាក់ប្រចាំការគ្រប់ពេលវេលា។
- តាមដានត្រួតពិនិត្យតំបន់ការងារកម្តៅរយៈពេលយ៉ាងតិច ៦០ នាទីបន្ទាប់ពីបញ្ចប់ការងារ ដើម្បីធានាថាមិនមានផ្សែង ឬរងើកភ្លើង។

៥. សិទ្ធិអំណាច និងការទទួលខុសត្រូវ AUTHORITY & RESPONSIBILITY
ប្រធានផ្នែកពាក់ព័ន្ធ និងមន្ត្រីទទួលបន្ទុកត្រូវធានាការអនុវត្តគោលការណ៍នេះឱ្យមានប្រសិទ្ធភាពខ្ពស់ និងរាយការណ៍ជូន General Manager។`,
    contentEn: `1. PURPOSE
To regulate high-risk hot work activities involving flames, grinding, and welding sparks, preventing catastrophic industrial fires.

2. SCOPE
Applies to all factory production areas, warehouses, administrative departments, and external contractors.

3. DEFINITIONS
- Compliance: Adherence to applicable national labor statutes, safety regulations, and buyer codes of conduct.
- Monitoring: Continuous routine verification to ensure sustained implementation.

4. PROCEDURE
- Obtain a verified Hot Work Permit signed by the EHS Officer at least 24 hours prior to commencing welding/cutting.
- Clear all flammable and combustible materials within an 11-meter (35-foot) radius of the operation zone.
- Position portable ABC dry powder extinguishers on-site and designate a trained Fire Watcher throughout the task.
- Maintain continuous fire surveillance for at least 60 minutes post-work to verify no smoldering embers remain.

5. AUTHORITY & RESPONSIBILITY
Designated department managers and compliance personnel are responsible for effective execution and reporting to the General Manager.`,
