    approvedDate: '11-11-2024',
    contentKh: `១. គោលបំណង PURPOSE
ដើម្បីកំណត់នីតិវិធីនៃការកាត់បន្ថយបុគ្គលិកជាបណ្តុំដោយសារវិបត្តិសេដ្ឋកិច្ច ឬការថយចុះការបញ្ជាទិញ ឱ្យស្របតាមមាត្រា ៩៥ នៃច្បាប់ការងារ។

២. ដែនកំណត់ SCOPE
គោលនយោបាយនេះអនុវត្តចំពោះគ្រប់ផ្នែកផលិតកម្ម រដ្ឋបាល ឃ្លាំង និងអ្នកម៉ៅការបន្តទាំងអស់ក្នុងរោងចក្រ។

៣. និយមន័យ DEFINITIONS
- អនុលោមភាព (Compliance): ការគោរព និងអនុវត្តតាមបទដ្ឋានច្បាប់ បទបញ្ជាផ្ទៃក្នុង និងស្តង់ដាអន្តរជាតិ។
- ការត្រួតពិនិត្យ (Monitoring): ដំណើរការតាមដានការអនុវត្តជាប្រចាំដើម្បីធានានិរន្តរភាព។

៤. នីតិវិធី PROCEDURE
- រៀបចំផែនការកាត់បន្ថយ និងពិភាក្សាជាមួយតំណាងសហជីព និងប្រតិភូបុគ្គលិកជាមុន។
- ជូនដំណឹង និងសុំការអនុញ្ញាតជាផ្លូវការពីអធិការការងារនៃក្រសួងការងារ និងបណ្តុះបណ្តាលវិជ្ជាជីវៈ។
- កំណត់លំដាប់លំដោយនៃការកាត់បន្ថយផ្អែកលើ៖ អតីតភាពការងារ បន្ទុកគ្រួសារ និងសមត្ថភាពវិជ្ជាជីវៈ។
- ទូទាត់ប្រាក់បំណាច់បញ្ចប់កិច្ចសន្យា ប្រាក់ជូនដំណឹង និងប្រាក់អតីតភាពការងារពេញលេញតាមច្បាប់។

៥. សិទ្ធិអំណាច និងការទទួលខុសត្រូវ AUTHORITY & RESPONSIBILITY
ប្រធានផ្នែកពាក់ព័ន្ធ និងមន្ត្រីទទួលបន្ទុកត្រូវធានាការអនុវត្តគោលការណ៍នេះឱ្យមានប្រសិទ្ធភាពខ្ពស់ និងរាយការណ៍ជូន General Manager។`,
    contentEn: `1. PURPOSE
To establish statutory retrenchment procedures during economic downturns per Article 95 of the Cambodian Labor Law.

2. SCOPE
Applies to all factory production areas, warehouses, administrative departments, and external contractors.

3. DEFINITIONS
- Compliance: Adherence to applicable national labor statutes, safety regulations, and buyer codes of conduct.
- Monitoring: Continuous routine verification to ensure sustained implementation.

4. PROCEDURE
- Formulate redundancy plans and conduct prior formal consultations with worker delegates and union leaders.
- Notify and seek statutory authorization from the Labor Inspectorate of the Ministry of Labor.
- Determine the order of layoffs based on statutory criteria: seniority, family dependents, and technical capability.
- Provide full legal severance payments, notice pay, and accrued statutory benefits per statutory labor schedules.

5. AUTHORITY & RESPONSIBILITY
Designated department managers and compliance personnel are responsible for effective execution and reporting to the General Manager.`,
