    preparedDate: '01-11-2024',
    approvedBy: 'Mr. CHEN LANMAO',
    approvedRole: 'នាយកក្រុមហ៊ុន General Manager',
    approvedDate: '11-11-2024',
    contentKh: `១. គោលបំណង PURPOSE
ដើម្បីធានាថារាល់ការធ្វើការថែមម៉ោង (OT) ត្រូវបានធ្វើឡើងដោយស្ម័គ្រចិត្ត ១០០% មិនលើសពីកម្រិតច្បាប់កំណត់ និងទូទាត់ប្រាក់ឈ្នួលត្រឹមត្រូវ។

២. ដែនកំណត់ SCOPE
គោលនយោបាយនេះអនុវត្តចំពោះគ្រប់ផ្នែកផលិតកម្ម រដ្ឋបាល ឃ្លាំង និងអ្នកម៉ៅការបន្តទាំងអស់ក្នុងរោងចក្រ។

៣. និយមន័យ DEFINITIONS
- អនុលោមភាព (Compliance): ការគោរព និងអនុវត្តតាមបទដ្ឋានច្បាប់ បទបញ្ជាផ្ទៃក្នុង និងស្តង់ដាអន្តរជាតិ។
- ការត្រួតពិនិត្យ (Monitoring): ដំណើរការតាមដានការអនុវត្តជាប្រចាំដើម្បីធានានិរន្តរភាព។

៤. នីតិវិធី PROCEDURE
- ការធ្វើការថែមម៉ោងត្រូវមានការយល់ព្រមស្ម័គ្រចិត្តពីកម្មករនិយោជិត ដោយចុះហត្ថលេខាលើទម្រង់ OT ស្ម័គ្រចិត្ត។
- ម៉ោងថែមមិនត្រូវលើសពី ២ ម៉ោងក្នុងមួយថ្ងៃ (សរុបមិនលើសពី ១០ ម៉ោងក្នុងមួយថ្ងៃ) និងធានាថ្ងៃសម្រាកប្រចាំសប្តាហ៍យ៉ាងតិច ១ ថ្ងៃ (២៤ ម៉ោងជាប់គ្នា)។
- គណនាប្រាក់ថែមម៉ោង៖ ១៥០% (ថ្ងៃធម្មតា), ២០០% (ថ្ងៃអាទិត្យ/បុណ្យជាតិ), និងប្រាក់បន្ថែមវេនយប់ (១៣០-២០០%)។
- សុំលិខិតអនុញ្ញាតថែមម៉ោងពីក្រសួងការងារជាផ្លូវការ។

៥. សិទ្ធិអំណាច និងការទទួលខុសត្រូវ AUTHORITY & RESPONSIBILITY
ប្រធានផ្នែកពាក់ព័ន្ធ និងមន្ត្រីទទួលបន្ទុកត្រូវធានាការអនុវត្តគោលការណ៍នេះឱ្យមានប្រសិទ្ធភាពខ្ពស់ និងរាយការណ៍ជូន General Manager។`,
    contentEn: `1. PURPOSE
To ensure all overtime work is strictly voluntary, within statutory hours limitations, and accurately compensated at premium rates.

2. SCOPE
Applies to all factory production areas, warehouses, administrative departments, and external contractors.

3. DEFINITIONS
- Compliance: Adherence to applicable national labor statutes, safety regulations, and buyer codes of conduct.
- Monitoring: Continuous routine verification to ensure sustained implementation.

4. PROCEDURE
- Overtime work requires explicit written voluntary consent signed by each worker on official overtime consent forms.
- Overtime shall not exceed 2 hours per day (maximum 10 daily work hours), guaranteeing at least one full 24-hour weekly rest day.
- Compensate overtime at statutory rates: 150% (normal days), 200% (Sundays and public holidays), and night-shift differentials.
- Obtain official statutory overtime authorization permits from the Ministry of Labor and Vocational Training.

5. AUTHORITY & RESPONSIBILITY
Designated department managers and compliance personnel are responsible for effective execution and reporting to the General Manager.`,
