    contentKh: `១. គោលបំណង PURPOSE
ដើម្បីកំណត់ម៉ោងធ្វើការស្តង់ដា ការបើកប្រាក់ឈ្នួលមិនទាបជាងកម្រិតអប្បបរមា និងការផ្តល់អត្ថប្រយោជន៍ស្របតាមច្បាប់ការងារ។

២. ដែនកំណត់ SCOPE
គោលនយោបាយនេះអនុវត្តចំពោះគ្រប់ផ្នែកផលិតកម្ម រដ្ឋបាល ឃ្លាំង និងអ្នកម៉ៅការបន្តទាំងអស់ក្នុងរោងចក្រ។

៣. និយមន័យ DEFINITIONS
- អនុលោមភាព (Compliance): ការគោរព និងអនុវត្តតាមបទដ្ឋានច្បាប់ បទបញ្ជាផ្ទៃក្នុង និងស្តង់ដាអន្តរជាតិ។
- ការត្រួតពិនិត្យ (Monitoring): ដំណើរការតាមដានការអនុវត្តជាប្រចាំដើម្បីធានានិរន្តរភាព។

៤. នីតិវិធី PROCEDURE
- ម៉ោងធ្វើការធម្មតា៖ ៨ ម៉ោងក្នុងមួយថ្ងៃ ឬ ៤៨ ម៉ោងក្នុងមួយសប្តាហ៍។
- ប្រាក់ឈ្នួលគោលត្រូវតែស្មើ ឬខ្ពស់ជាងប្រាក់ឈ្នួលអប្បបរមាដែលកំណត់ដោយប្រកាសក្រសួងការងារ។
- ផ្តល់អត្ថប្រយោជន៍ស្របច្បាប់៖ ប្រាក់រង្វាន់ទៀងទាត់ (Attendance Bonus), ប្រាក់ឧបត្ថម្ភស្នាក់នៅ/ធ្វើដំណើរ, និងប្រាក់អតីតភាព (Seniority Indemnity) ២ ដង/ឆ្នាំ។
- ចែកចាយប័ណ្ណបើកប្រាក់ខែ (Pay Slip) ជូនកម្មករម្នាក់ៗយ៉ាងតិច ២ ថ្ងៃមុនថ្ងៃបើកប្រាក់។

៥. សិទ្ធិអំណាច និងការទទួលខុសត្រូវ AUTHORITY & RESPONSIBILITY
ប្រធានផ្នែកពាក់ព័ន្ធ និងមន្ត្រីទទួលបន្ទុកត្រូវធានាការអនុវត្តគោលការណ៍នេះឱ្យមានប្រសិទ្ធភាពខ្ពស់ និងរាយការណ៍ជូន General Manager។`,
    contentEn: `1. PURPOSE
To define standard work hours, enforce legal minimum wage thresholds, and disburse mandatory statutory allowances transparently.

2. SCOPE
Applies to all factory production areas, warehouses, administrative departments, and external contractors.

3. DEFINITIONS
- Compliance: Adherence to applicable national labor statutes, safety regulations, and buyer codes of conduct.
- Monitoring: Continuous routine verification to ensure sustained implementation.

4. PROCEDURE
- Standard working hours are capped at 8 hours per day and 48 hours per week.
- Basic wages strictly equal or exceed the official minimum wage established by annual Ministerial Praka.
- Provide statutory benefits: monthly attendance bonus, housing/transportation allowances, and bi-annual seniority indemnities.
- Distribute transparent, detailed pay slips to all workers at least 2 days prior to salary disbursement.

5. AUTHORITY & RESPONSIBILITY
Designated department managers and compliance personnel are responsible for effective execution and reporting to the General Manager.`,
