    preparedRole: 'ប្រធានរដ្ឋបាល/ធនធានមនុស្ស HR/Admin Manager',
    preparedDate: '01-11-2024',
    approvedBy: 'Mr. CHEN LANMAO',
    approvedRole: 'នាយកក្រុមហ៊ុន General Manager',
    approvedDate: '11-11-2024',
    contentKh: `១. គោលបំណង PURPOSE
ដើម្បីផ្សព្វផ្សាយ និងអនុវត្តបទបញ្ជាផ្ទៃក្នុងដែលបានអនុម័តដោយក្រសួងការងារ ធានាវិន័យការងារ និងការយល់ដឹងពីសិទ្ធិរបស់កម្មករ។

២. ដែនកំណត់ SCOPE
គោលនយោបាយនេះអនុវត្តចំពោះគ្រប់ផ្នែកផលិតកម្ម រដ្ឋបាល ឃ្លាំង និងអ្នកម៉ៅការបន្តទាំងអស់ក្នុងរោងចក្រ។

៣. និយមន័យ DEFINITIONS
- អនុលោមភាព (Compliance): ការគោរព និងអនុវត្តតាមបទដ្ឋានច្បាប់ បទបញ្ជាផ្ទៃក្នុង និងស្តង់ដាអន្តរជាតិ។
- ការត្រួតពិនិត្យ (Monitoring): ដំណើរការតាមដានការអនុវត្តជាប្រចាំដើម្បីធានានិរន្តរភាព។

៤. នីតិវិធី PROCEDURE
- បទបញ្ជាផ្ទៃក្នុងត្រូវបិទផ្សាយនៅទីតាំងបើកចំហ (ដូចជា ក្តារព័ត៌មានរោងចក្រ) ជាភាសាខ្មែរ។
- ចែកសៀវភៅណែនាំបុគ្គលិក (Employee Handbook) ជូនកម្មករថ្មីម្នាក់មួយក្បាលនៅថ្ងៃតម្រង់ទិស។
- ខ្លឹមសារគ្របដណ្តប់៖ ម៉ោងការងារ ការឈប់សម្រាក វិន័យ វិធានការសុវត្ថិភាព សិទ្ធិ និងកាតព្វកិច្ច។
- ការកែប្រែបទបញ្ជាផ្ទៃក្នុងត្រូវមានការយល់ព្រមពីតំណាងកម្មករ និងចុះទិដ្ឋាការពីក្រសួងការងារ។

៥. សិទ្ធិអំណាច និងការទទួលខុសត្រូវ AUTHORITY & RESPONSIBILITY
ប្រធានផ្នែកពាក់ព័ន្ធ និងមន្ត្រីទទួលបន្ទុកត្រូវធានាការអនុវត្តគោលការណ៍នេះឱ្យមានប្រសិទ្ធភាពខ្ពស់ និងរាយការណ៍ជូន General Manager។`,
    contentEn: `1. PURPOSE
To promulgate factory internal regulations approved by the Ministry of Labor, governing workplace order, rights, and duties.

2. SCOPE
Applies to all factory production areas, warehouses, administrative departments, and external contractors.

3. DEFINITIONS
- Compliance: Adherence to applicable national labor statutes, safety regulations, and buyer codes of conduct.
- Monitoring: Continuous routine verification to ensure sustained implementation.

4. PROCEDURE
- Display official ministry-approved Internal Regulations visibly on factory notice boards in Khmer.
- Provide a copy of the Employee Handbook to every newly recruited worker during induction training.
- Contents span work hours, leave entitlements, disciplinary scales, health and safety rules, and grievance channels.
- Any amendment to internal regulations requires consultation with worker delegates and official ministry visa approval.

5. AUTHORITY & RESPONSIBILITY
Designated department managers and compliance personnel are responsible for effective execution and reporting to the General Manager.`,
