    approvedBy: 'Mr. CHEN LANMAO',
    approvedRole: 'នាយកក្រុមហ៊ុន General Manager',
    approvedDate: '11-11-2024',
    contentKh: `១. គោលបំណង PURPOSE
ដើម្បីគ្រប់គ្រង ការបែងចែក ការផ្ទុក និងការបោះចោលសំណល់រឹង សំណល់គ្រោះថ្នាក់ និងសំណល់កែច្នៃស្របតាមច្បាប់បរិស្ថាន។

២. ដែនកំណត់ SCOPE
គោលនយោបាយនេះអនុវត្តចំពោះគ្រប់ផ្នែកផលិតកម្ម រដ្ឋបាល ឃ្លាំង និងអ្នកម៉ៅការបន្តទាំងអស់ក្នុងរោងចក្រ។

៣. និយមន័យ DEFINITIONS
- អនុលោមភាព (Compliance): ការគោរព និងអនុវត្តតាមបទដ្ឋានច្បាប់ បទបញ្ជាផ្ទៃក្នុង និងស្តង់ដាអន្តរជាតិ។
- ការត្រួតពិនិត្យ (Monitoring): ដំណើរការតាមដានការអនុវត្តជាប្រចាំដើម្បីធានានិរន្តរភាព។

៤. នីតិវិធី PROCEDURE
- បែងចែកធុងសំរាមតាមកូដពណ៌៖ ពណ៌ខៀវ (សំណល់កែច្នៃ), ពណ៌បៃតង (សំណល់សរីរាង្គ/អាហារ), ពណ៌ក្រហម (សំណល់គ្រោះថ្នាក់/កាកសំណល់គីមី)។
- ផ្ទុកសំណល់គ្រោះថ្នាក់ (កំប៉ុងគីមី អំពូលភ្លើង ប្រេងម៉ាស៊ីនចាស់) ក្នុងបន្ទប់ផ្ទុកសំណល់គ្រោះថ្នាក់ដែលមានសោចាក់ត្រឹមត្រូវ។
- ប្រគល់សំណល់គ្រោះថ្នាក់ទៅឱ្យក្រុមហ៊ុនដែលមានអាជ្ញាបណ្ណពីក្រសួងបរិស្ថានយកទៅកម្ទេចចោល។
- រក្សាទុកកិច្ចសន្យា និងលិខិតបញ្ជាក់ការដឹកជញ្ជូនសំណល់ (Waste Manifest) សម្រាប់សវនកម្ម។

៥. សិទ្ធិអំណាច និងការទទួលខុសត្រូវ AUTHORITY & RESPONSIBILITY
ប្រធានផ្នែកពាក់ព័ន្ធ និងមន្ត្រីទទួលបន្ទុកត្រូវធានាការអនុវត្តគោលការណ៍នេះឱ្យមានប្រសិទ្ធភាពខ្ពស់ និងរាយការណ៍ជូន General Manager។`,
    contentEn: `1. PURPOSE
To classify, segregate, store, and dispose of industrial solid, hazardous, and recyclable wastes per environmental statutes.

2. SCOPE
Applies to all factory production areas, warehouses, administrative departments, and external contractors.

3. DEFINITIONS
- Compliance: Adherence to applicable national labor statutes, safety regulations, and buyer codes of conduct.
- Monitoring: Continuous routine verification to ensure sustained implementation.

4. PROCEDURE
- Segregate waste using color-coded bins: Blue (recyclables/paper), Green (organic/food waste), Red (hazardous/chemical waste).
- Store hazardous wastes (used chemical drums, fluorescent tubes, spent oils) in locked, bunded hazardous waste bays.
- Contract exclusively with licensed waste management vendors certified by the Ministry of Environment for hazardous disposal.
- Archive consignment notes and hazardous waste manifests for mandatory compliance verification.

5. AUTHORITY & RESPONSIBILITY
Designated department managers and compliance personnel are responsible for effective execution and reporting to the General Manager.`,
