    approvedDate: '11-11-2024',
    contentKh: `១. គោលបំណង PURPOSE
ដើម្បីការពារទិន្នន័យផ្ទាល់ខ្លួន ព័ត៌មានប្រាក់បៀវត្សរ៍ និងឯកសារសម្ងាត់របស់បុគ្គលិកគ្រប់រូប ស្របតាមច្បាប់ការពារទិន្នន័យ។

២. ដែនកំណត់ SCOPE
គោលនយោបាយនេះអនុវត្តចំពោះគ្រប់ផ្នែកផលិតកម្ម រដ្ឋបាល ឃ្លាំង និងអ្នកម៉ៅការបន្តទាំងអស់ក្នុងរោងចក្រ។

៣. និយមន័យ DEFINITIONS
- អនុលោមភាព (Compliance): ការគោរព និងអនុវត្តតាមបទដ្ឋានច្បាប់ បទបញ្ជាផ្ទៃក្នុង និងស្តង់ដាអន្តរជាតិ។
- ការត្រួតពិនិត្យ (Monitoring): ដំណើរការតាមដានការអនុវត្តជាប្រចាំដើម្បីធានានិរន្តរភាព។

៤. នីតិវិធី PROCEDURE
- ទិន្នន័យផ្ទាល់ខ្លួន (អត្តសញ្ញាណប័ណ្ណ គណនីធនាគារ កំណត់ត្រាសុខភាព) ត្រូវរក្សាទុកក្នុងទូដែកមានសោ ឬប្រព័ន្ធកុំព្យូទ័រដែលមាន Password។
- មានតែបុគ្គលិក HR ដែលមានការចាត់តាំងប៉ុណ្ណោះ ទើបមានសិទ្ធិចូលមើលទិន្នន័យទាំងនេះ។
- ហាមដាច់ខាតការចែករំលែក ឬលក់ព័ត៌មានផ្ទាល់ខ្លួនរបស់បុគ្គលិកទៅកាន់ភាគីទីបីដោយគ្មានការយល់ព្រម។
- បុគ្គលិកមានសិទ្ធិស្នើសុំពិនិត្យ និងកែតម្រូវព័ត៌មានផ្ទាល់ខ្លួនរបស់ខ្លួនឱ្យបានត្រឹមត្រូវ។

៥. សិទ្ធិអំណាច និងការទទួលខុសត្រូវ AUTHORITY & RESPONSIBILITY
ប្រធានផ្នែកពាក់ព័ន្ធ និងមន្ត្រីទទួលបន្ទុកត្រូវធានាការអនុវត្តគោលការណ៍នេះឱ្យមានប្រសិទ្ធភាពខ្ពស់ និងរាយការណ៍ជូន General Manager។`,
    contentEn: `1. PURPOSE
To safeguard personal data, medical files, banking info, and privacy rights of all factory employees against unauthorized disclosure.

2. SCOPE
Applies to all factory production areas, warehouses, administrative departments, and external contractors.

3. DEFINITIONS
- Compliance: Adherence to applicable national labor statutes, safety regulations, and buyer codes of conduct.
- Monitoring: Continuous routine verification to ensure sustained implementation.

4. PROCEDURE
- Store personal records (national IDs, bank numbers, medical records) in locked fireproof cabinets or encrypted HRIS databases.
- Restrict file access strictly to designated, authorized HR management personnel bound by confidentiality agreements.
- Strictly prohibit sharing, leaking, or transferring employee personal data to third parties without written consent.
- Employees hold the legal right to review, update, and rectify inaccuracies in their personal personnel files.

5. AUTHORITY & RESPONSIBILITY
Designated department managers and compliance personnel are responsible for effective execution and reporting to the General Manager.`,
