    preparedDate: '01-11-2024',
    approvedBy: 'Mr. CHEN LANMAO',
    approvedRole: 'នាយកក្រុមហ៊ុន General Manager',
    approvedDate: '11-11-2024',
    contentKh: `១. គោលបំណង PURPOSE
ដើម្បីធានាការផ្តល់ទឹកស្អាតមានគុណភាព និងលើកកម្ពស់អនាម័យនៃការប្រើប្រាស់ដបទឹកផ្ទាល់ខ្លួន បង្ការជំងឺឆ្លង។

២. ដែនកំណត់ SCOPE
គោលនយោបាយនេះអនុវត្តចំពោះគ្រប់ផ្នែកផលិតកម្ម រដ្ឋបាល ឃ្លាំង និងអ្នកម៉ៅការបន្តទាំងអស់ក្នុងរោងចក្រ។

៣. និយមន័យ DEFINITIONS
- អនុលោមភាព (Compliance): ការគោរព និងអនុវត្តតាមបទដ្ឋានច្បាប់ បទបញ្ជាផ្ទៃក្នុង និងស្តង់ដាអន្តរជាតិ។
- ការត្រួតពិនិត្យ (Monitoring): ដំណើរការតាមដានការអនុវត្តជាប្រចាំដើម្បីធានានិរន្តរភាព។

៤. នីតិវិធី PROCEDURE
- ក្រុមហ៊ុនផ្តល់ជូនទឹកស្អាត RO (Reverse Osmosis) ដោយឥតគិតថ្លៃនៅគ្រប់រោងជាង និងកន្លែងបរិភោគអាហារ។
- ធ្វើតេស្តគុណភាពទឹកផឹកដោយមន្ទីរពិសោធន៍ឯករាជ្យយ៉ាងតិច ២ ដងក្នុងមួយឆ្នាំ (តេស្តមីក្រូជីវសាស្ត្រ និងគីមី)។
- ផ្តល់ដបទឹកផ្ទាល់ខ្លួនដល់កម្មករម្នាក់មួយ និងណែនាំឱ្យលាងសម្អាតដបទឹកជារៀងរាល់ថ្ងៃ។
- ហាមដាច់ខាតការប្រើប្រាស់កែវទឹករួមគ្នា ឬការយកដបទឹកទៅដាក់ផ្ទាល់លើតុម៉ាស៊ីនដេរ (ត្រូវដាក់ក្នុងថាសទឹក)។

៥. សិទ្ធិអំណាច និងការទទួលខុសត្រូវ AUTHORITY & RESPONSIBILITY
ប្រធានផ្នែកពាក់ព័ន្ធ និងមន្ត្រីទទួលបន្ទុកត្រូវធានាការអនុវត្តគោលការណ៍នេះឱ្យមានប្រសិទ្ធភាពខ្ពស់ និងរាយការណ៍ជូន General Manager។`,
    contentEn: `1. PURPOSE
To guarantee safe drinking water access and mandate personal drinking bottle hygiene, preventing communicable waterborne illnesses.

2. SCOPE
Applies to all factory production areas, warehouses, administrative departments, and external contractors.

3. DEFINITIONS
- Compliance: Adherence to applicable national labor statutes, safety regulations, and buyer codes of conduct.
- Monitoring: Continuous routine verification to ensure sustained implementation.

4. PROCEDURE
- Provide certified UV/RO treated purified drinking water free of charge across all manufacturing and dining areas.
- Submit water samples for independent laboratory microbiological and chemical testing at least twice annually.
- Supply sanitized personal reusable water bottles to all workers, mandating daily washing hygiene.
- Strictly prohibit sharing drinking cups; water bottles must be placed in designated under-table cup holders.

5. AUTHORITY & RESPONSIBILITY
Designated department managers and compliance personnel are responsible for effective execution and reporting to the General Manager.`,
