    approvedDate: '11-11-2024',
    contentKh: `១. គោលបំណង PURPOSE
ដើម្បីធានាថាបុគ្គលិកថ្មីទាំងអស់យល់ដឹងច្បាស់ពីបទបញ្ជាផ្ទៃក្នុង សិទ្ធិការងារ សុវត្ថិភាព និងវប្បធម៌រោងចក្រ មុនចាប់ផ្តើមការងារ។

២. ដែនកំណត់ SCOPE
គោលនយោបាយនេះអនុវត្តចំពោះគ្រប់ផ្នែកផលិតកម្ម រដ្ឋបាល ឃ្លាំង និងអ្នកម៉ៅការបន្តទាំងអស់ក្នុងរោងចក្រ។

៣. និយមន័យ DEFINITIONS
- អនុលោមភាព (Compliance): ការគោរព និងអនុវត្តតាមបទដ្ឋានច្បាប់ បទបញ្ជាផ្ទៃក្នុង និងស្តង់ដាអន្តរជាតិ។
- ការត្រួតពិនិត្យ (Monitoring): ដំណើរការតាមដានការអនុវត្តជាប្រចាំដើម្បីធានានិរន្តរភាព។

៤. នីតិវិធី PROCEDURE
- រៀបចំវគ្គតម្រង់ទិសរយៈពេលកន្លះថ្ងៃ (៤ ម៉ោង) ដល់បុគ្គលិកថ្មីទាំងអស់នៅថ្ងៃដំបូងនៃការចូលធ្វើការ។
- មេរៀនគ្របដណ្តប់៖ បទបញ្ជាផ្ទៃក្នុង ម៉ោងការងារ ប្រាក់ឈ្នួល ច្បាប់ឈប់សម្រាក សុវត្ថិភាពអគ្គិភ័យ និងការដាក់បណ្តឹងតវ៉ា។
- នាំបុគ្គលិកថ្មីដើរទស្សនកិច្ចរោងចក្រ បង្ហាញច្រកចេញសង្គ្រោះបន្ទាន់ បន្ទប់ទឹក បន្ទប់សុខភាព និងអាហារដ្ឋាន។
- បុគ្គលិកថ្មីត្រូវចុះហត្ថលេខាលើបញ្ជីវត្តមាន និងលិខិតបញ្ជាក់ការយល់ព្រមគោរពតាមបទបញ្ជាផ្ទៃក្នុង។

៥. សិទ្ធិអំណាច និងការទទួលខុសត្រូវ AUTHORITY & RESPONSIBILITY
ប្រធានផ្នែកពាក់ព័ន្ធ និងមន្ត្រីទទួលបន្ទុកត្រូវធានាការអនុវត្តគោលការណ៍នេះឱ្យមានប្រសិទ្ធភាពខ្ពស់ និងរាយការណ៍ជូន General Manager។`,
    contentEn: `1. PURPOSE
To ensure all newly onboarded personnel understand factory internal regulations, labor rights, safety rules, and grievance channels.

2. SCOPE
Applies to all factory production areas, warehouses, administrative departments, and external contractors.

3. DEFINITIONS
- Compliance: Adherence to applicable national labor statutes, safety regulations, and buyer codes of conduct.
- Monitoring: Continuous routine verification to ensure sustained implementation.

4. PROCEDURE
- Conduct a structured 4-hour orientation session for all new hires on their first day prior to floor placement.
- Curriculum covers internal regulations, wage systems, leave policies, fire evacuation, PPE, and grievance mechanisms.
- Guide workers on a facility tour identifying emergency fire exits, clinic location, clean restrooms, and cafeteria.
- New hires sign the official orientation attendance register and written pledge acknowledging company regulations.

5. AUTHORITY & RESPONSIBILITY
Designated department managers and compliance personnel are responsible for effective execution and reporting to the General Manager.`,
