    titleKh: 'គោលការណ៍ការពារបរិស្ថាន និងកាត់បន្ថយផលប៉ះពាល់លើសមុទ្រនិងមហាសមុទ្រ',
    titleEn: 'Marine and Ocean Ecosystem Protection Policy',
    companyName: 'G.S.textileGarment(Cambodia) co.,Ltd',
    productType: 'Garment & Textile Products',
    preparedBy: 'Mr. CHAN PHEARUM',
    preparedRole: 'ប្រធានរដ្ឋបាល/ធនធានមនុស្ស HR/Admin Manager',
    preparedDate: '01-11-2024',
    approvedBy: 'Mr. CHEN LANMAO',
    approvedRole: 'នាយកក្រុមហ៊ុន General Manager',
    approvedDate: '11-11-2024',
    contentKh: `១. គោលបំណង PURPOSE
ដើម្បីទប់ស្កាត់ការបំពុលពីកាកសំណល់ប្លាស្ទិក ជាតិគីមី និងទឹកកខ្វក់ មិនឱ្យហូរចូលទៅក្នុងប្រព័ន្ធទឹកសមុទ្រ និងមហាសមុទ្រ។

២. ដែនកំណត់ SCOPE
គោលនយោបាយនេះអនុវត្តចំពោះគ្រប់ផ្នែកផលិតកម្ម រដ្ឋបាល ឃ្លាំង និងអ្នកម៉ៅការបន្តទាំងអស់ក្នុងរោងចក្រ។

៣. និយមន័យ DEFINITIONS
- អនុលោមភាព (Compliance): ការគោរព និងអនុវត្តតាមបទដ្ឋានច្បាប់ បទបញ្ជាផ្ទៃក្នុង និងស្តង់ដាអន្តរជាតិ។
- ការត្រួតពិនិត្យ (Monitoring): ដំណើរការតាមដានការអនុវត្តជាប្រចាំដើម្បីធានានិរន្តរភាព។

៤. នីតិវិធី PROCEDURE
- ហាមឃាត់ការបង្ហូរទឹកកខ្វក់ដែលមិនទាន់ឆ្លងកាត់ការប្រព្រឹត្តិកម្ម (Untreated Wastewater) ចូលទៅក្នុងប្រព័ន្ធលូសាធារណៈ ឬប្រភពទឹកធម្មជាតិ។
- អនុវត្តវិធានការ ZDHC MRSL ដើម្បីលុបបំបាត់ការប្រើប្រាស់សារធាតុគីមីគ្រោះថ្នាក់ក្នុងដំណើរការបោកគក់ និងផលិត។
- គ្រប់គ្រងសំណល់ប្លាស្ទិក ថង់វេចខ្ចប់ និងខ្សែចង មិនឱ្យហើរឬហូរចូលទៅក្នុងប្រឡាយទឹក។
- ចូលរួមយុទ្ធនាការកាត់បន្ថយការប្រើប្រាស់ប្លាស្ទិកដែលប្រើបានតែម្តង (Single-use Plastics) ក្នុងរោងចក្រ។

៥. សិទ្ធិអំណាច និងការទទួលខុសត្រូវ AUTHORITY & RESPONSIBILITY
ប្រធានផ្នែកពាក់ព័ន្ធ និងមន្ត្រីទទួលបន្ទុកត្រូវធានាការអនុវត្តគោលការណ៍នេះឱ្យមានប្រសិទ្ធភាពខ្ពស់ និងរាយការណ៍ជូន General Manager។`,
    contentEn: `1. PURPOSE
To eliminate factory plastic pellet leakage, toxic chemical discharges, and untreated wastewater into marine and coastal ecosystems.

2. SCOPE
Applies to all factory production areas, warehouses, administrative departments, and external contractors.

3. DEFINITIONS
- Compliance: Adherence to applicable national labor statutes, safety regulations, and buyer codes of conduct.
- Monitoring: Continuous routine verification to ensure sustained implementation.

4. PROCEDURE
- Strictly prohibit discharging untreated industrial effluent into public drainage, streams, or waterways.
- Enforce the ZDHC Manufacturing Restricted Substances List (MRSL), phasing out hazardous processing chemicals.
- Secure all plastic packaging, polybags, and strapping bands within enclosed compactors preventing environmental drift.
- Promote factory-wide reduction campaigns targeting single-use disposable plastics in packaging and dining areas.

5. AUTHORITY & RESPONSIBILITY
Designated department managers and compliance personnel are responsible for effective execution and reporting to the General Manager.`,
