    contentKh: `១. គោលបំណង PURPOSE
ដើម្បីធានាថាប្រតិបត្តិការរោងចក្រអនុលោម ១០០% តាមច្បាប់ស្តីពីការការពារបរិស្ថាន និងការគ្រប់គ្រងធនធានធម្មជាតិនៃព្រះរាជាណាចក្រកម្ពុជា។

២. ដែនកំណត់ SCOPE
គោលនយោបាយនេះអនុវត្តចំពោះគ្រប់ផ្នែកផលិតកម្ម រដ្ឋបាល ឃ្លាំង និងអ្នកម៉ៅការបន្តទាំងអស់ក្នុងរោងចក្រ។

៣. និយមន័យ DEFINITIONS
- អនុលោមភាព (Compliance): ការគោរព និងអនុវត្តតាមបទដ្ឋានច្បាប់ បទបញ្ជាផ្ទៃក្នុង និងស្តង់ដាអន្តរជាតិ។
- ការត្រួតពិនិត្យ (Monitoring): ដំណើរការតាមដានការអនុវត្តជាប្រចាំដើម្បីធានានិរន្តរភាព។

៤. នីតិវិធី PROCEDURE
- ស្នើសុំ និងរក្សាទុកលិខិតអនុញ្ញាតបរិស្ថាន (Environmental Permits) ពីក្រសួងបរិស្ថានឱ្យបានទាន់ពេលវេលា។
- ធ្វើការវាយតម្លៃផលប៉ះពាល់បរិស្ថាន (EIA/IEIA) និងអនុវត្តតាមផែនការគ្រប់គ្រងបរិស្ថាន (EMP) ដែលបានអនុម័ត។
- ធ្វើតេស្តគុណភាពខ្យល់ ផ្សែងបំពង់ ទឹកសំណល់ និងកម្រិតសំឡេងជាប្រចាំដោយមន្ទីរពិសោធន៍ទទួលស្គាល់ដោយរដ្ឋ។
- ធ្វើរបាយការណ៍បរិស្ថានប្រចាំត្រីមាស និងប្រចាំឆ្នាំផ្ញើជូនមន្ទីរ និងក្រសួងបរិស្ថាន។

៥. សិទ្ធិអំណាច និងការទទួលខុសត្រូវ AUTHORITY & RESPONSIBILITY
ប្រធានផ្នែកពាក់ព័ន្ធ និងមន្ត្រីទទួលបន្ទុកត្រូវធានាការអនុវត្តគោលការណ៍នេះឱ្យមានប្រសិទ្ធភាពខ្ពស់ និងរាយការណ៍ជូន General Manager។`,
    contentEn: `1. PURPOSE
To guarantee comprehensive adherence to Cambodian environmental laws, ministerial sub-decrees, and environmental permits.

2. SCOPE
Applies to all factory production areas, warehouses, administrative departments, and external contractors.

3. DEFINITIONS
- Compliance: Adherence to applicable national labor statutes, safety regulations, and buyer codes of conduct.
- Monitoring: Continuous routine verification to ensure sustained implementation.

4. PROCEDURE
- Obtain and maintain valid environmental discharge permits and operational authorizations from the Ministry of Environment.
- Implement all mitigation measures committed in approved Initial Environmental Impact Assessments (IEIA/EMP).
- Commission licensed testing of stack emissions, ambient air, wastewater discharge, and noise levels periodically.
- Submit quarterly and annual environmental compliance reports to municipal and national environmental authorities.

5. AUTHORITY & RESPONSIBILITY
Designated department managers and compliance personnel are responsible for effective execution and reporting to the General Manager.`,
