    titleEn: 'Chemical and Material Inventory Log Standard',
    companyName: 'G.S.textileGarment(Cambodia) co.,Ltd',
    productType: 'Garment & Textile Products',
    preparedBy: 'Mr. CHAN PHEARUM',
    preparedRole: 'ប្រធានរដ្ឋបាល/ធនធានមនុស្ស HR/Admin Manager',
    preparedDate: '01-11-2024',
    approvedBy: 'Mr. CHEN LANMAO',
    approvedRole: 'នាយកក្រុមហ៊ុន General Manager',
    approvedDate: '11-11-2024',
    contentKh: `១. គោលបំណង PURPOSE
ដើម្បីគ្រប់គ្រងទិន្នន័យស្តុកសារធាតុគីមី សម្ភារគ្រោះថ្នាក់ និងគ្រឿងបន្លាស់ឱ្យមានតម្លាភាព តាមដានការប្រើប្រាស់ និងធានាសុវត្ថិភាព។

២. ដែនកំណត់ SCOPE
គោលនយោបាយនេះអនុវត្តចំពោះគ្រប់ផ្នែកផលិតកម្ម រដ្ឋបាល ឃ្លាំង និងអ្នកម៉ៅការបន្តទាំងអស់ក្នុងរោងចក្រ។

៣. និយមន័យ DEFINITIONS
- អនុលោមភាព (Compliance): ការគោរព និងអនុវត្តតាមបទដ្ឋានច្បាប់ បទបញ្ជាផ្ទៃក្នុង និងស្តង់ដាអន្តរជាតិ។
- ការត្រួតពិនិត្យ (Monitoring): ដំណើរការតាមដានការអនុវត្តជាប្រចាំដើម្បីធានានិរន្តរភាព។

៤. នីតិវិធី PROCEDURE
- រក្សាតារាងកត់ត្រាស្តុកគីមី (Chemical Inventory List) បង្ហាញឈ្មោះគីមី បរិមាណ ទីតាំង និងលេខ SDS យ៉ាងច្បាស់លាស់។
- កត់ត្រារាល់ការនាំចូល ការបើកប្រើប្រាស់ និងការសេសសល់ជារៀងរាល់ថ្ងៃលើតារាង Log Sheet (កំណត់ត្រាផ្ទុកសម្ភារ)។
- ផ្ទៀងផ្ទាត់សារធាតុគីមីទាំងអស់ធៀបនឹងបញ្ជីហាមឃាត់ ZDHC MRSL មុនពេលបញ្ជាទិញចូលរោងចក្រ។
- ត្រួតពិនិត្យស្តុកជាក់ស្តែងធៀបនឹងតារាងកត់ត្រាប្រចាំខែ (Monthly Chemical Reconciliation)។

៥. សិទ្ធិអំណាច និងការទទួលខុសត្រូវ AUTHORITY & RESPONSIBILITY
ប្រធានផ្នែកពាក់ព័ន្ធ និងមន្ត្រីទទួលបន្ទុកត្រូវធានាការអនុវត្តគោលការណ៍នេះឱ្យមានប្រសិទ្ធភាពខ្ពស់ និងរាយការណ៍ជូន General Manager។`,
    contentEn: `1. PURPOSE
To maintain comprehensive inventory records and track the usage, storage balances, and disposal of chemicals and industrial supplies.

2. SCOPE
Applies to all factory production areas, warehouses, administrative departments, and external contractors.

3. DEFINITIONS
- Compliance: Adherence to applicable national labor statutes, safety regulations, and buyer codes of conduct.
- Monitoring: Continuous routine verification to ensure sustained implementation.

4. PROCEDURE
- Maintain an updated Chemical Inventory Register detailing commercial names, quantities, CAS numbers, and SDS locations.
- Record daily chemical receipts, department dispensing, and balance on hand in the standard material storage register.
- Screen all chemical inputs against the ZDHC MRSL prohibited substances database prior to purchasing approval.
- Conduct monthly physical stock reconciliations verifying recorded quantities against actual storage weights.

5. AUTHORITY & RESPONSIBILITY
Designated department managers and compliance personnel are responsible for effective execution and reporting to the General Manager.`,
